import itertools

def solve_tiling(R, C):
    # S-tetramino shapes
    shapes = [
        [(1,0), (2,0), (0,1), (1,1)], # Shape 1
        [(0,0), (1,0), (1,1), (2,1)], # Shape 2
        [(1,0), (0,1), (1,1), (0,2)], # Shape 3
        [(0,0), (0,1), (1,1), (1,2)], # Shape 4
    ]

    # Generate all possible placements of S-tetraminoes
    placements = []
    for r in range(R):
        for c in range(C):
            for shape in shapes:
                cells = []
                for dr, dc in shape:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < R and 0 <= nc < C:
                        cells.append((nr, nc))
                    else:
                        break
                if len(cells) == 4:
                    placements.append(frozenset(cells))

    # Backtracking to find tiling
    def backtrack(uncovered):
        if not uncovered:
            return True

        # Pick the first uncovered cell
        cell = next(iter(uncovered))

        # Try all placements that cover this cell
        for p in placements:
            if cell in p and p.issubset(uncovered):
                if backtrack(uncovered - p):
                    return True
        return False

    return backtrack(set((r, c) for r in range(R) for c in range(C)))

