def solve_min_dominoes(R, C):
    # S-tetramino shapes
    s_shapes = [
        [(1,0), (2,0), (0,1), (1,1)],
        [(0,0), (1,0), (1,1), (2,1)],
        [(1,0), (0,1), (1,1), (0,2)],
        [(0,0), (0,1), (1,1), (1,2)],
    ]
    # Domino shapes
    d_shapes = [
        [(0,0), (1,0)],
        [(0,0), (0,1)],
    ]

    # Generate all possible placements
    s_placements = []
    for r in range(R):
        for c in range(C):
            for shape in s_shapes:
                cells = []
                for dr, dc in shape:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < R and 0 <= nc < C:
                        cells.append((nr, nc))
                    else:
                        break
                if len(cells) == 4:
                    s_placements.append(frozenset(cells))

    d_placements = []
    for r in range(R):
        for c in range(C):
            for shape in d_shapes:
                cells = []
                for dr, dc in shape:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < R and 0 <= nc < C:
                        cells.append((nr, nc))
                    else:
                        break
                if len(cells) == 2:
                    d_placements.append(frozenset(cells))

    # We want to minimize the number of dominoes.
    # Try d = 0, 1, 2, ...
    for d_count in range(0, (R*C)//2 + 1):
        # This is still too slow. Let's use a more efficient backtracking.
        # To use d_count dominoes, we need s = (R*C - 2*d_count) / 4 S-tetrominoes.
        if (R*C - 2*d_count) % 4 != 0:
            continue
        s_count = (R*C - 2*d_count) // 4

        def backtrack(uncovered, s_rem, d_rem):
            if not uncovered:
                return s_rem == 0 and d_rem == 0

            cell = next(iter(uncovered))

            # Try S-tetrominoes
            if s_rem > 0:
                for p in s_placements:
                    if cell in p and p.issubset(uncovered):
                        if backtrack(uncovered - p, s_rem - 1, d_rem):
                            return True

            # Try dominoes
            if d_rem > 0:
                for p in d_placements:
                    if cell in p and p.issubset(uncovered):
                        if backtrack(uncovered - p, s_rem, d_rem - 1):
                            return True
            return False

        if backtrack(set((r, c) for r in range(R) for c in range(C)), s_count, d_count):
            return d_count
    return None

